BEGIN;

CREATE TABLE IF NOT EXISTS "public"."menu_categories" (
    "id" uuid PRIMARY KEY,
    "name" varchar(80) NOT NULL,
    "description" varchar(255),
    "display_order" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL
        CHECK ("display_order" >= 0),
    "isActive" boolean NOT NULL DEFAULT true,
    "createdAt" timestamptz NOT NULL DEFAULT now(),
    "updatedAt" timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS "menu_categories_name_lower_unique"
    ON "public"."menu_categories" (LOWER("name"));
CREATE INDEX IF NOT EXISTS "menu_categories_display_order_idx"
    ON "public"."menu_categories" ("display_order");
CREATE INDEX IF NOT EXISTS "menu_categories_active_idx"
    ON "public"."menu_categories" ("isActive");

INSERT INTO "public"."menu_categories" ("id", "name", "createdAt", "updatedAt")
SELECT gen_random_uuid(), normalized.category_name, now(), now()
FROM (
    SELECT MIN(category_name) AS category_name
    FROM (
        SELECT COALESCE(NULLIF(BTRIM("category"), ''), 'Uncategorized') AS category_name
        FROM "public"."menu_items"
    ) AS source_categories
    GROUP BY LOWER(category_name)
    ORDER BY LOWER(MIN(category_name))
) AS normalized
ON CONFLICT DO NOTHING;

ALTER TABLE "public"."menu_items"
    ADD COLUMN IF NOT EXISTS "categoryId" uuid;

UPDATE "public"."menu_items" AS item
SET "categoryId" = category.id,
    "category" = category.name
FROM "public"."menu_categories" AS category
WHERE LOWER(category.name) =
    LOWER(COALESCE(NULLIF(BTRIM(item."category"), ''), 'Uncategorized'))
  AND item."categoryId" IS NULL;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM "public"."menu_items"
        WHERE "categoryId" IS NULL
    ) THEN
        RAISE EXCEPTION 'Unable to associate every menu item with a menu category.';
    END IF;
END
$$;

ALTER TABLE "public"."menu_items"
    ALTER COLUMN "categoryId" SET NOT NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'menu_items_category_id_fkey'
          AND conrelid = '"public"."menu_items"'::regclass
    ) THEN
        ALTER TABLE "public"."menu_items"
            ADD CONSTRAINT "menu_items_category_id_fkey"
            FOREIGN KEY ("categoryId")
            REFERENCES "public"."menu_categories" ("id")
            ON DELETE RESTRICT;
    END IF;
END
$$;

CREATE INDEX IF NOT EXISTS "menu_items_category_id_idx"
    ON "public"."menu_items" ("categoryId");

COMMIT;
